/* Hallmark · pre-emit critique: P5 H4 E4 S5 R5 V4 · one editable daily record across map and itinerary */
(() => {
  const safe=value=>escapeHtml(String(value??''));
  const amount=value=>Number.isFinite(Number(value))&&Number(value)>0?Number(value):0;
  const fields=[['area','当天所在地区','例如：开罗、达哈布'],['flight','航班 / 火车 / 巴士编号','例如：MS 958；没有可留空'],['from','从哪里出发','机场、上一家酒店或城市'],['to','到哪里','市区、下一座城市或酒店'],['transport','到达与换城方式','打车、接机、巴士、火车…'],['departTime','出发时间',''],['arriveTime','抵达时间',''],['hotel','今晚住哪里','酒店或民宿名称'],['hotelArea','住宿地址 / 街区','方便第二天接着走'],['activities','当天其他安排','吃饭、休息、自由活动等'],['notes','提醒自己','入住时间、接送集合点等']];
  const field=(key,label,placeholder='',value='')=>`<label class="field"><span>${label}</span><input name="${key}" value="${safe(value)}" placeholder="${safe(placeholder)}" maxlength="160"></label>`;
  const money=(key,label,value)=>`<label class="field"><span>${label} · ¥</span><input name="${key}" type="number" min="0" step="1" inputmode="decimal" value="${safe(value)}" placeholder="0"></label>`;
  const oldSave=saveTrip;
  saveTrip=function(next){const old=state.editTrip;if(old?.id===next.id){next.days?.forEach((day,i)=>{const previous=old.days?.find(item=>item.date===day.date)||old.days?.[i];if(previous?.daily&&!day.daily)day.daily=previous.daily})}return oldSave(next)};
  const oldDiscover=renderDiscover;
  renderDiscover=function(){const html=oldDiscover(),headingAt=html.indexOf('这段旅程附近值得去')>=0?html.indexOf('这段旅程附近值得去'):html.indexOf('先从这里开始'),start=html.lastIndexOf('<div class="section-heading">',headingAt),next=html.indexOf('你的下一站',headingAt),end=html.lastIndexOf('<div class="section-heading">',next);if(start<0||end<=start)return html;const choices=[['egypt','埃及','沿着历史与河流'],['paris','法国 · 巴黎','在城市里慢慢走'],['kyoto','日本 · 京都','住下来，逛街与寺院'],['beijing','中国 · 北京','从熟悉的地方出发'],['xian','中国 · 西安','城墙与博物馆']].filter(([key])=>CATALOG[key]);const guide=`<section class="home-choose"><div class="section-heading"><h2 class="section-title">你想去哪个国家？</h2></div><p class="section-note">还没决定也没关系。先挑一个方向，再看那里的城市、博物馆和景点。</p><div class="home-destinations">${choices.map(([key,title,subtitle])=>`<button class="home-destination" data-action="destination" data-key="${key}">${image(CATALOG[key].photo,CATALOG[key].name)}<span><strong>${title}</strong><small>${subtitle}</small></span><span aria-hidden="true">↗</span></button>`).join('')}</div></section>`;return html.slice(0,start)+guide+html.slice(end)};
  function dayCard(day,i){const d=day.daily||{},cost=amount(d.transportCost)+amount(d.hotelCost)+amount(d.foodCost)+amount(d.activityCost),filled=Object.values(d).some(Boolean);return `<details class="daily-card" data-index="${i}"><summary><span class="daily-number">${String(i+1).padStart(2,'0')}</span><span class="daily-summary"><strong>第${i+1}天 · ${prettyDate(day.date)}</strong><small>${safe(d.area||'地区待填写')} · ${safe(d.hotel||'住宿待填写')}</small></span><span class="daily-chevron">${filled?'编辑':'填写'} ↗</span></summary><div class="daily-body"><p class="daily-help">这一天的抵达、换城和住处都记在这里；景点仍在下方增减。空白不会被当成已预订。</p><form class="daily-form" data-day="${i}"><div class="daily-fields">${field('area','当天所在地区','例如：开罗、达哈布',d.area)}${money('dayBudget','当天预算',d.dayBudget)}</div><h3>01 · 到达与移动</h3><div class="daily-fields">${field('flight','航班 / 火车 / 巴士编号','例如：MS 958',d.flight)}${field('transport','交通方式','打车、接机、巴士、火车…',d.transport)}${field('from','从哪里出发','机场、上一家酒店或城市',d.from)}${field('to','到哪里','市区、下一座城市或酒店',d.to)}<label class="field"><span>出发时间（当地）</span><input name="departTime" type="time" value="${safe(d.departTime)}"></label><label class="field"><span>抵达时间（当地）</span><input name="arriveTime" type="time" value="${safe(d.arriveTime)}"></label>${money('transportCost','交通预算',d.transportCost)}</div><h3>02 · 今晚住哪里</h3><div class="daily-fields">${field('hotel','酒店 / 民宿','例如：开罗市中心的酒店',d.hotel)}${field('hotelArea','地址 / 街区','例如：解放广场附近',d.hotelArea)}${money('hotelCost','住宿预算',d.hotelCost)}</div><h3>03 · 当天安排与花费</h3><div class="daily-fields">${money('foodCost','餐饮预算',d.foodCost)}${money('activityCost','门票 / 活动预算',d.activityCost)}</div><label class="field"><span>其他安排</span><textarea name="activities" rows="3" maxlength="500" placeholder="例如：抵达后休息，傍晚到市区散步">${safe(d.activities)}</textarea></label><label class="field"><span>备注</span><textarea name="notes" rows="2" maxlength="500" placeholder="例如：接机集合点、入住时间">${safe(d.notes)}</textarea></label><div class="daily-total"><span>已填分类合计</span><strong>¥${cost.toLocaleString()}</strong><small>当天预算 ¥${amount(d.dayBudget).toLocaleString()} · 金额均为你填写的人民币计划，不是实时报价</small></div><button class="primary full" type="submit">保存第${i+1}天安排</button></form></div></details>`}
  const oldRender=renderTrip;
  renderTrip=function(){const html=oldRender(),t=trip();if(!t)return html;const panel=`<section class="daily-workspace" id="daily-workspace"><div class="section-heading"><h2 class="section-title">每天真正怎么走</h2></div><p class="section-note">把航班、机场到市区、换城市、每天住哪和预算写进同一份行程。埃及地图上的地点会同步到下方每日景点。</p><div class="daily-list">${t.days.map(dayCard).join('')}</div><p class="daily-local-note">资料只保存在这个浏览器。不要填写证件号、支付信息或订单验证码。</p></section>`;return html.replace('<div id="weatherPanel"',`${panel}<div id="weatherPanel"`).replace('完整旅行工作台','旅行账本与票据').replace('已接入 Travel-Plan-Page：路线示意、逐日行程、门票状态、出发事项与多人记账。','每日安排就在本页编辑；原工作台保留多人记账与票据。').replace('打开工作台 ↗','打开旅行账本 ↗')};
  document.addEventListener('submit',event=>{const form=event.target.closest?.('.daily-form');if(!form)return;event.preventDefault();const t=trip(),index=Number(form.dataset.day),day=t?.days?.[index];if(!day)return;const data=new FormData(form),daily={};for(const [key] of fields)daily[key]=String(data.get(key)||'').trim().slice(0,key==='notes'||key==='activities'?500:160);for(const key of ['dayBudget','transportCost','hotelCost','foodCost','activityCost'])daily[key]=amount(data.get(key));day.daily=daily;saveTrip(t);render();document.querySelector(`.daily-card[data-index="${index}"]`)?.setAttribute('open','');notify(`第${index+1}天的安排已保存`)});
  const openId=new URLSearchParams(location.search).get('openTrip');if(openId&&storeGet().some(item=>item.id===openId))goto('trip',{tripId:openId});else render();
})();
